mapper.select:
SELECT
    (
        ( SELECT COUNT(*)
          FROM trade_order
          WHERE customer_id = #{customerId}
            AND create_date = CURRENT_DATE()   -- 只检查今天创建的订单
            AND order_status < 3                  -- 状态1表示未付款，状态2表示已关闭
        ) >= 10                                -- 数量是否达到或超过10笔
            OR
        ( SELECT COUNT(*)
          FROM trade_order
          WHERE customer_id = #{customerId}
            AND refund_date = CURRENT_DATE()  -- 只检查今天退款的订单
            AND order_status = 4                    -- 状态值为4表示已退款
        ) >= 5                                -- 数量是否达到或超过5笔
        ) AS illegal

SELECT o.order_id as orderId, o.out_trade_no AS outTradeNo, o.goods_id AS goodsId, o.snapshot_id AS snapshotId, o.goods_title AS goodsTitle, o.goods_price AS goodsPrice, o.quantity, o.total_amount AS totalAmount, o.goods_image AS goodsImage, o.goods_description AS goodsDescription, o.`order_status` AS orderStatus, IF(o.`order_status` = 1 AND TIMESTAMPDIFF(MINUTE,o.create_time,NOW()) > 20, true, false) AS disabled, DATE_FORMAT(o.create_date,"%Y-%m-%d") AS createDate, DATE_FORMAT(o.create_time,"%Y-%m-%d %H:%i:%s") AS createTime, COUNT(a.order_id) AS appointCount FROM trade_order o LEFT JOIN med_exam_appointment a ON o.order_id = a.order_id WHERE o.customer_id = #{customerId}
AND o.`order_status` = #{orderStatus}
AND ( o.out_trade_no = #{keyword} OR o.goods_title LIKE CONCAT( "%", #{keyword}, "%" ) )
GROUP BY o.order_id ORDER BY o.order_id DESC LIMIT #{startIndex}, #{pageSize}

SELECT COUNT(*)
FROM trade_order
WHERE customer_id = #{customerId}

    AND `order_status` = #{orderStatus}


    AND ( out_trade_no = #{keyword} OR goods_title LIKE CONCAT( "%", #{keyword}, "%" ) )

select o.goods_title as goodsTitle, o.goods_price as goodsPrice, o.quantity, o.total_amount as totalAmount, o.order_status as orderStatus, date_format(o.create_time, '%Y-%m-%d %H:%i') as createTime, o.create_date as createDate, date_format(o.refund_time, '%Y-%m-%d %H:%i') as refundTime, o.refund_date as refundDate, o.order_id as orderId, c.photo_url as photoUrl, c.customer_name as customerName, c.gender, c.phone, date_format(c.register_time, '%Y-%m-%d') as registerTime, o.out_trade_no as outTradeNo, o.transaction_id as transactionId, o.out_refund_no as outRefundNo, o.snapshot_id as snapshotId, count(a.order_id) as num from med_exam_package p join trade_order o on p.id = o.goods_id join crm_customer c on c.id = o.customer_id left join med_exam_appointment a on a.order_id = o.order_id
and o.customer_id = #{customerId}
p.package_code like concat('%',#{packageCode},'%')
and o.goods_title like concat('%',#{keyword},'%')
and c.phone = #{phone}
and o.order_status = #{orderStatus}
and o.create_date between #{startDate} and #{endDate}
group by o.order_id order by o.order_id desc limit #{startIndex}, #{pageSize}

select count(*) from med_exam_package p join trade_order o on p.id = o.goods_id join crm_customer c on c.id = o.customer_id
p.package_code like concat('%',#{packageCode},'%')
and o.goods_title like concat('%',#{keyword},'%')
and c.phone = #{phone}
and o.order_status = #{orderStatus}
and o.create_date between #{startDate} and #{endDate}

/* ShardingSphere hint: dataSourceName=write_a */
select o.order_id as orderId,
       o.quantity as n1,
       (select count(*) from med_exam_appointment where order_id=o.order_id and status=3) as n2
from trade_order o join med_exam_appointment a on o.order_id=a.order_id
WHERE a.appointment_no = #{appointmentNo}
